(() => {
  const U=window.RentFlowUtils, P=window.RentFlowProperties, T=window.RentFlowTenants, L=window.RentFlowLeases, Pay=window.RentFlowPayments, M=window.RentFlowMaintenance, R=window.RentFlowReports;
  let db=window.RentFlowStorage.load(), currentPage="dashboard", propertySearch="", tenantSearch="", paymentFilter="all", maintenanceFilter="all", reportStart="2026-10-01", reportEnd="2026-10-31";
  const content=document.getElementById("page-content"), modalRoot=document.getElementById("modal-root");
  document.getElementById("current-year").textContent=new Date().getFullYear();
  document.querySelectorAll("[data-icon]").forEach(node=>node.innerHTML=U.icon(node.dataset.icon));
  const save=()=>{const ok=window.RentFlowStorage.save(db);if(!ok)U.toast("Could not save. Browser storage may be full.","error");};
  const propertyName=id=>P.getById(db,id)?.name||"Unknown property";
  const unitById=id=>db.units.find(u=>u.id===id);
  const unitLabel=id=>{const u=unitById(id);return u?`${propertyName(u.propertyId)} · ${u.unitNumber}`:"Unassigned";};
  const tenantName=id=>T.getById(db,id)?.fullName||"Unknown tenant";
  const leaseById=id=>db.leases.find(l=>l.id===id);
  const obligationLease=o=>leaseById(o.leaseId);
  const obligationTenant=o=>tenantName(obligationLease(o)?.tenantId);
  const activeLeases=(asOf=U.today())=>db.leases.filter(l=>l.status==="active"&&l.startDate<=asOf&&l.endDate>=asOf);
  const pageTitle={dashboard:"Dashboard",properties:"Properties",tenants:"Tenants",payments:"Rent & Payments",maintenance:"Maintenance",reports:"Reports",settings:"Settings"};
  const heading=(eyebrow,title,subtitle,actions="")=>`<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;
  const stat=(label,value,icon,color,note)=>`<article class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${color}">${U.icon(icon)}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></article>`;
  const panelHeader=(title,subtitle,action="")=>`<div class="panel-header"><div><h2 class="panel-title">${title}</h2><p class="panel-subtitle">${subtitle}</p></div>${action}</div>`;
  const avatar=(name,color="blue")=>`<span class="avatar avatar-${color}">${U.initials(name)}</span>`;
  const actions=(id,type)=>`<div class="inline-actions"><button class="icon-action" title="View details" aria-label="View details" data-action="view-${type}" data-id="${id}">${U.icon("eye")}</button><button class="icon-action" title="Edit" aria-label="Edit" data-action="edit-${type}" data-id="${id}">${U.icon("edit")}</button></div>`;
  const render=()=>{
    document.getElementById("page-crumb").textContent=pageTitle[currentPage]||"Dashboard";
    document.querySelectorAll(".nav-item[data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===currentPage));
    document.getElementById("nav-property-count").textContent=db.properties.filter(p=>!p.archived).length;
    document.getElementById("nav-maintenance-count").textContent=M.openItems(db).length;
    const pages={dashboard:renderDashboard,properties:renderProperties,tenants:renderTenants,payments:renderPayments,maintenance:renderMaintenance,reports:renderReports,settings:renderSettings};
    content.innerHTML=(pages[currentPage]||renderDashboard)();
    content.querySelectorAll("[data-icon]").forEach(node=>node.innerHTML=U.icon(node.dataset.icon));
  };
  function renderDashboard(){
    const today=U.today(), active=activeLeases(), occ=R.occupancy(db), currentMonth=today.slice(0,7), monthStart=currentMonth+"-01";
    const collected=Pay.collected(db,monthStart,today), outstanding=R.outstanding(db,today), open=M.openItems(db);
    const recent=[...db.payments].filter(p=>p.status==="valid").sort((a,b)=>b.paymentDate.localeCompare(a.paymentDate)).slice(0,5);
    const expiring=db.leases.filter(l=>l.status==="active"&&l.endDate>=today&&l.endDate<=new Date(Date.now()+30*86400000).toISOString().slice(0,10)).slice(0,4);
    const monthLabels=["May","Jun","Jul","Aug","Sep","Oct"], monthValues=monthLabels.map((_,i)=>{const d=new Date();d.setMonth(d.getMonth()-(5-i));const m=d.toISOString().slice(0,7);return Pay.collected(db,m+"-01",m+"-31");});
    const max=Math.max(...monthValues,1), points=monthValues.map((v,i)=>`${18+i*58},${160-(v/max)*115}`).join(" ");
    const chart=`<div class="chart-wrap"><svg viewBox="0 0 370 210" role="img" aria-label="Rent collected over the last six months"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#5275eb" stop-opacity=".22"/><stop offset="100%" stop-color="#5275eb" stop-opacity="0"/></linearGradient></defs>${[45,85,125,165].map(y=>`<line x1="12" y1="${y}" x2="360" y2="${y}" stroke="#eef1f7" stroke-dasharray="3 4"/>`).join("")}<polygon points="18,180 ${points} 308,180" fill="url(#chartFill)"/><polyline points="${points}" fill="none" stroke="#5275eb" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${monthValues.map((v,i)=>`<circle cx="${18+i*58}" cy="${160-(v/max)*115}" r="3.5" fill="#fff" stroke="#5275eb" stroke-width="2"/>`).join("")}${monthLabels.map((m,i)=>`<text x="${18+i*58}" y="198" text-anchor="middle" font-size="10" fill="#9ba3b2">${m}</text>`).join("")}</svg></div>`;
    return `${heading("OVERVIEW","Good morning, John 👋","Here’s what’s happening across your rental portfolio.",`${U.button(`${U.icon("plus")} Add property`,"add-property","secondary")} ${U.button(`${U.icon("plus")} Record payment`,"add-payment","primary")}`)}
      <div class="stat-grid">${stat("Total properties",db.properties.filter(p=>!p.archived).length,U.money?"building":"building","blue",`${db.units.filter(u=>!u.archived).length} rental units in your portfolio`)}${stat("Occupied units",`${occ.occupied} <span style="font-size:12px;color:#8993a6;font-weight:600">/ ${occ.total}</span>`,"users","green",`${occ.rate}% occupancy rate`)}${stat("Rent collected",U.money(collected),"wallet","purple",`Payments received this month`)}${stat("Outstanding rent",U.money(outstanding),"coin","orange",`${db.obligations.filter(o=>Pay.status(db,o,today)==="overdue").length} overdue obligations`)}</div>
      <div class="content-grid"><section class="panel">${panelHeader("Rent collection","Payment activity over the last six months",`<span class="chart-legend"><span><i class="legend-dot" style="background:#5275eb"></i>Collected</span></span>`)}<div class="panel-body">${chart}</div></section>
      <section class="panel">${panelHeader("Recent payments","Latest recorded transactions",`<button class="text-link" data-page="payments">View all ${U.icon("chevron")}</button>`)}<div class="panel-body"><div class="mini-list">${recent.length?recent.map(p=>`<div class="mini-row">${avatar(obligationTenant(db.obligations.find(o=>o.id===p.obligationId)||{}),"green")}<div class="mini-main"><strong>${U.esc(obligationTenant(db.obligations.find(o=>o.id===p.obligationId)||{}))}</strong><small>${U.date(p.paymentDate)} · ${U.esc(p.method)}</small></div><div class="mini-amount">${U.money(p.amount)}<small>${U.badge("paid","Received")}</small></div></div>`).join(""):`<div class="empty-state">No payments recorded yet.</div>`}</div></div></section></div>
      <div class="content-grid"><section class="panel table-panel">${panelHeader("Rent status","Current rent obligations",`<button class="text-link" data-page="payments">Manage rent ${U.icon("chevron")}</button>`)}<div class="table-wrap"><table class="responsive-table"><thead><tr><th>Tenant</th><th>Unit</th><th>Due date</th><th>Amount</th><th>Status</th></tr></thead><tbody>${db.obligations.slice(0,5).map(o=>`<tr><td data-label="Tenant"><div class="table-primary">${avatar(obligationTenant(o))}<span>${U.esc(obligationTenant(o))}</span></div></td><td data-label="Unit">${U.esc(unitById(obligationLease(o)?.unitId)?.unitNumber||"—")}</td><td data-label="Due date">${U.date(o.dueDate)}</td><td data-label="Amount">${U.money(o.amountDue)}</td><td data-label="Status">${U.badge(Pay.status(db,o))}</td></tr>`).join("")}</tbody></table></div></section>
      <section class="panel">${panelHeader("Needs attention","Items worth a closer look")}<div class="panel-body">${open.slice(0,3).map(m=>`<div class="mini-row"><span class="stat-icon ${m.priority==="urgent"||m.priority==="high"?"orange":"blue"}">${U.icon("wrench")}</span><div class="mini-main"><strong>${U.esc(m.title)}</strong><small>${U.esc(propertyName(m.propertyId))} · ${U.date(m.reportedAt)}</small></div>${U.badge(m.priority)}</div>`).join("")||`<div class="empty-state">Everything looks clear.</div>`}${expiring.length?`<div class="notice-card" style="margin-top:12px"><span>◷</span><div><strong>${expiring.length} lease${expiring.length===1?"":"s"} expiring soon</strong><p>${expiring.map(l=>U.esc(tenantName(l.tenantId))).join(", ")}</p></div></div>`:""}</div></section></div>`;
  }
  function renderProperties(){
    const items=db.properties.filter(p=>!p.archived&&`${p.name} ${p.address} ${p.type}`.toLowerCase().includes(propertySearch.toLowerCase()));
    return `${heading("YOUR PORTFOLIO","Properties","Manage buildings, rental units, and occupancy at a glance.",U.button(`${U.icon("plus")} Add property`,"add-property","primary"))}
      <div class="filter-row"><label class="global-search"><span data-icon="search">${U.icon("search")}</span><input id="property-search" value="${U.esc(propertySearch)}" placeholder="Search properties..." aria-label="Search properties"></label><span class="muted">${items.length} properties</span></div>
      <div class="property-grid">${items.map((p,i)=>{const units=P.units(db,p.id),occupied=P.occupiedUnitIds(db),count=units.filter(u=>occupied.has(u.id)).length,monthly=activeLeases().filter(l=>units.some(u=>u.id===l.unitId)).reduce((s,l)=>s+l.rentAmount,0);return `<article class="property-card"><div class="property-art tone-${i%4+1}"><span class="property-art-label">${U.icon("building")} ${U.esc(p.type)}</span></div><div class="property-card-body"><div class="property-card-title"><h3>${U.esc(p.name)}</h3>${U.badge(count===units.length&&units.length?"active":"available",count===units.length&&units.length?"Fully occupied":"Portfolio")}</div><p class="property-address">${U.esc(p.address)}</p><div class="property-metrics"><div class="property-metric"><small>Monthly rent</small><strong>${U.money(monthly)}</strong></div><div class="property-metric"><small>Units occupied</small><strong>${count} of ${units.length}</strong><div class="occupancy-track"><span style="width:${units.length?count/units.length*100:0}%"></span></div></div></div><div class="property-card-footer"><span class="muted" style="font-size:10px">${units.length} unit${units.length===1?"":"s"}</span><div class="inline-actions">${U.button("View units",`view-property`,"secondary","btn-sm").replace('data-action="view-property"','data-action="view-property" data-id="'+p.id+'"')}${U.button("Edit","edit-property","secondary","btn-sm").replace('data-action="edit-property"','data-action="edit-property" data-id="'+p.id+'"')}</div></div></div></article>`}).join("")||`<div class="panel empty-state" style="grid-column:1/-1"><strong>No properties found</strong>Try a different search or add a property.</div>`}</div>`;
  }
  function renderTenants(){
    const items=db.tenants.filter(t=>!t.archived&&`${t.fullName} ${t.phone} ${t.email}`.toLowerCase().includes(tenantSearch.toLowerCase()));
    return `${heading("PEOPLE","Tenants","Keep tenant details and lease relationships organized.",`${U.button(`${U.icon("plus")} Create lease`,"add-lease","secondary")} ${U.button(`${U.icon("plus")} Add tenant`,"add-tenant","primary")}`)}
      <div class="panel table-panel"><div class="panel-header"><div><h2 class="panel-title">Tenant directory</h2><p class="panel-subtitle">${items.length} tenant profiles</p></div><button class="btn btn-secondary btn-sm" data-action="export-tenants">${U.icon("download")} Export CSV</button></div><div class="table-toolbar"><label class="global-search"><span>${U.icon("search")}</span><input id="tenant-search" value="${U.esc(tenantSearch)}" placeholder="Search tenants..." aria-label="Search tenants"></label><span class="muted">Demo data</span></div><div class="table-wrap"><table class="responsive-table"><thead><tr><th>Tenant</th><th>Contact</th><th>Current unit</th><th>Lease ends</th><th>Status</th><th>Actions</th></tr></thead><tbody>${items.map(t=>{const l=T.currentLease(db,t.id);return `<tr><td data-label="Tenant"><div class="table-primary">${avatar(t.fullName)}<span>${U.esc(t.fullName)}<small>Added ${U.date(t.createdAt)}</small></span></div></td><td data-label="Contact">${U.esc(t.phone)}<small style="display:block;color:#9aa1b0;margin-top:3px">${U.esc(t.email||"No email")}</small></td><td data-label="Current unit">${U.esc(l?unitLabel(l.unitId):"No active lease")}</td><td data-label="Lease ends">${U.date(l?.endDate)}</td><td data-label="Status">${U.badge(l?"active":"available",l?"Active tenant":"No active lease")}</td><td data-label="Actions">${actions(t.id,"tenant")}</td></tr>`}).join("")||`<tr><td colspan="6"><div class="empty-state"><strong>No tenants found</strong>Try a different search.</div></td></tr>`}</tbody></table></div></div>`;
  }
  function renderPayments(){
    const items=db.obligations.filter(o=>paymentFilter==="all"||Pay.status(db,o)===paymentFilter).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));
    const paid=db.obligations.reduce((s,o)=>s+Pay.paid(db,o.id),0),due=db.obligations.reduce((s,o)=>s+o.amountDue,0),outstanding=db.obligations.reduce((s,o)=>s+Pay.balance(db,o),0);
    return `${heading("FINANCIALS","Rent & Payments","Track rent obligations, partial payments, and outstanding balances.",`${U.button(`${U.icon("plus")} Create rent due`,"add-obligation","secondary")} ${U.button(`${U.icon("plus")} Record payment`,"add-payment","primary")}`)}
      <div class="stat-grid">${stat("Rent due",U.money(due),"calendar","blue","Across listed obligations")}${stat("Payments received",U.money(paid),"wallet","green","Valid payments only")}${stat("Outstanding balance",U.money(outstanding),"coin","orange","Remaining across obligations")}${stat("Overdue obligations",db.obligations.filter(o=>Pay.status(db,o)==="overdue").length,"bell","purple","Past due with no payment")}</div>
      <div class="panel table-panel"><div class="panel-header"><div><h2 class="panel-title">Rent obligations</h2><p class="panel-subtitle">A rent due record is separate from its payment history.</p></div><button class="btn btn-secondary btn-sm" data-action="export-payments">${U.icon("download")} Export CSV</button></div><div class="table-toolbar"><div class="toolbar-filters"><select class="field-control" id="payment-filter" aria-label="Filter rent status"><option value="all" ${paymentFilter==="all"?"selected":""}>All statuses</option><option value="paid" ${paymentFilter==="paid"?"selected":""}>Paid</option><option value="partial" ${paymentFilter==="partial"?"selected":""}>Partially paid</option><option value="unpaid" ${paymentFilter==="unpaid"?"selected":""}>Unpaid</option><option value="overdue" ${paymentFilter==="overdue"?"selected":""}>Overdue</option></select></div><span class="muted">${items.length} obligations</span></div><div class="table-wrap"><table class="responsive-table"><thead><tr><th>Tenant / unit</th><th>Rent period</th><th>Due date</th><th>Amount due</th><th>Paid</th><th>Balance</th><th>Status</th><th>Actions</th></tr></thead><tbody>${items.map(o=>{const l=obligationLease(o);return `<tr><td data-label="Tenant / unit"><div class="table-primary">${avatar(obligationTenant(o))}<span>${U.esc(obligationTenant(o))}<small>${U.esc(unitById(l?.unitId)?.unitNumber||"—")} · ${U.esc(propertyName(unitById(l?.unitId)?.propertyId))}</small></span></div></td><td data-label="Rent period">${U.date(o.periodStart)} – ${U.date(o.periodEnd)}</td><td data-label="Due date">${U.date(o.dueDate)}</td><td data-label="Amount due">${U.money(o.amountDue)}</td><td data-label="Paid">${U.money(Pay.paid(db,o.id))}</td><td data-label="Balance"><strong>${U.money(Pay.balance(db,o))}</strong></td><td data-label="Status">${U.badge(Pay.status(db,o))}</td><td data-label="Actions"><div class="inline-actions"><button class="icon-action" data-action="view-obligation" data-id="${o.id}" title="Payment history" aria-label="Payment history">${U.icon("eye")}</button><button class="icon-action" data-action="pay-obligation" data-id="${o.id}" title="Record payment" aria-label="Record payment">${U.icon("wallet")}</button></div></td></tr>`}).join("")||`<tr><td colspan="8"><div class="empty-state">No obligations match this filter.</div></td></tr>`}</tbody></table></div></div>`;
  }
  function renderMaintenance(){
    const items=db.maintenance.filter(m=>maintenanceFilter==="all"||m.status===maintenanceFilter).sort((a,b)=>b.reportedAt.localeCompare(a.reportedAt));
    const open=M.openItems(db).length, urgent=db.maintenance.filter(m=>m.priority==="urgent"&&m.status!=="completed"&&m.status!=="cancelled").length, spend=db.maintenance.filter(m=>m.status==="completed").reduce((s,m)=>s+Number(m.cost||0),0);
    return `${heading("PROPERTY CARE","Maintenance","Log repair requests, prioritize work, and keep a record of costs.",U.button(`${U.icon("plus")} New request`,"add-maintenance","primary"))}
      <div class="stat-grid">${stat("Open requests",open,"wrench","blue","Open and in progress")}${stat("Urgent items",urgent,"bell","orange","Needs prompt attention")}${stat("Completed jobs",db.maintenance.filter(m=>m.status==="completed").length,"chart","green","All recorded time")}${stat("Recorded costs",U.money(spend),"coin","purple","Completed maintenance only")}</div>
      <div class="panel table-panel"><div class="panel-header"><div><h2 class="panel-title">Maintenance requests</h2><p class="panel-subtitle">Track issues from report through completion.</p></div><button class="btn btn-secondary btn-sm" data-action="export-maintenance">${U.icon("download")} Export CSV</button></div><div class="table-toolbar"><div class="toolbar-filters"><select class="field-control" id="maintenance-filter" aria-label="Filter maintenance status"><option value="all">All statuses</option><option value="open" ${maintenanceFilter==="open"?"selected":""}>Open</option><option value="in-progress" ${maintenanceFilter==="in-progress"?"selected":""}>In progress</option><option value="completed" ${maintenanceFilter==="completed"?"selected":""}>Completed</option><option value="cancelled" ${maintenanceFilter==="cancelled"?"selected":""}>Cancelled</option></select></div><span class="muted">${items.length} requests</span></div><div class="table-wrap"><table class="responsive-table"><thead><tr><th>Request</th><th>Property / unit</th><th>Priority</th><th>Reported</th><th>Cost</th><th>Status</th><th>Actions</th></tr></thead><tbody>${items.map(m=>`<tr><td data-label="Request"><div class="table-primary"><span class="mini-avatar">${U.icon("wrench")}</span><span>${U.esc(m.title)}<small>${U.esc(tenantName(m.tenantId))}</small></span></div></td><td data-label="Property / unit">${U.esc(propertyName(m.propertyId))}<small style="display:block;color:#9aa1b0;margin-top:3px">${U.esc(unitById(m.unitId)?.unitNumber||"Property-wide")}</small></td><td data-label="Priority">${U.badge(m.priority)}</td><td data-label="Reported">${U.date(m.reportedAt)}</td><td data-label="Cost">${U.money(m.cost||0)}</td><td data-label="Status">${U.badge(m.status)}</td><td data-label="Actions">${actions(m.id,"maintenance")}</td></tr>`).join("")||`<tr><td colspan="7"><div class="empty-state">No maintenance requests found.</div></td></tr>`}</tbody></table></div></div>`;
  }
  function renderReports(){
    const collected=Pay.collected(db,reportStart,reportEnd),due=R.rentDue(db,reportStart,reportEnd),expenses=M.expenses(db,reportStart,reportEnd),occ=R.occupancy(db);
    const propRows=db.properties.filter(p=>!p.archived).map(p=>{const units=P.units(db,p.id),occupied=P.occupiedUnitIds(db);return {p,units,count:units.filter(u=>occupied.has(u.id)).length};});
    return `${heading("INSIGHTS","Reports","Understand rent collection, occupancy, and maintenance costs.",U.button(`${U.icon("download")} Export rent report`,"export-report","primary"))}
      <div class="panel" style="margin-bottom:18px"><div class="panel-header"><div><h2 class="panel-title">Reporting period</h2><p class="panel-subtitle">Payment reports use the payment date; rent due reports use the obligation due date.</p></div></div><div class="panel-body"><div class="filter-row" style="margin-bottom:0"><div class="form-field"><label for="report-start">From</label><input class="field-control" type="date" id="report-start" value="${reportStart}"></div><div class="form-field"><label for="report-end">To</label><input class="field-control" type="date" id="report-end" value="${reportEnd}"></div><button class="btn btn-secondary" data-action="apply-report">Apply dates</button></div></div></div>
      <div class="report-grid"><div class="report-card"><small>Rent collected in period</small><strong>${U.money(collected)}</strong><p>Valid payments received between selected dates</p></div><div class="report-card"><small>Rent due in period</small><strong>${U.money(due)}</strong><p>Obligations due between selected dates</p></div><div class="report-card"><small>Maintenance costs</small><strong>${U.money(expenses)}</strong><p>Completed jobs within the selected period</p></div><div class="report-card"><small>Occupancy rate</small><strong>${occ.rate}%</strong><p>${occ.occupied} of ${occ.total} units occupied today</p></div><div class="report-card"><small>Total outstanding</small><strong>${U.money(R.outstanding(db))}</strong><p>Due balances as of today</p></div><div class="report-card"><small>Open maintenance</small><strong>${M.openItems(db).length}</strong><p>Open and in-progress requests</p></div></div>
      <div class="content-grid"><section class="panel">${panelHeader("Occupancy by property","Active leases as of today")}<div class="panel-body">${propRows.map(({p,units,count})=>`<div class="progress-row"><span>${U.esc(p.name.length>17?p.name.slice(0,16)+"…":p.name)}</span><div class="progress-bar"><span style="width:${units.length?count/units.length*100:0}%"></span></div><strong>${units.length?Math.round(count/units.length*100):0}%</strong></div>`).join("")}</div></section><section class="panel">${panelHeader("Maintenance overview","Current status mix")}<div class="panel-body">${["open","in-progress","completed","cancelled"].map(s=>`<div class="mini-row"><div class="mini-main"><strong>${s==="in-progress"?"In progress":s[0].toUpperCase()+s.slice(1)}</strong><small>Maintenance requests</small></div><div class="mini-amount">${db.maintenance.filter(m=>m.status===s).length}</div></div>`).join("")}</div></section></div>`;
  }
  function renderSettings(){
    return `${heading("PREFERENCES","Settings","Manage your demo workspace, data, and backup options.")}
      <div class="settings-layout"><div class="settings-menu"><button class="active" type="button">General settings</button><button type="button" data-action="backup">Backup &amp; restore</button><button type="button" data-action="reset-demo">Reset demo data</button></div><section class="settings-panel"><h2>Workspace preferences</h2><p>These settings are stored locally in this browser.</p><form id="settings-form"><div class="form-grid"><div class="form-field"><label for="owner-name">Owner name</label><input id="owner-name" name="ownerName" value="${U.esc(db.settings.ownerName||"")}" required></div><div class="form-field"><label for="business-name">Portfolio name</label><input id="business-name" name="businessName" value="${U.esc(db.settings.businessName||"")}" required></div><div class="form-field"><label for="currency">Currency</label><select id="currency" disabled><option>NGN — Nigerian naira (₦)</option></select><span class="form-help">RentFlow V1 is configured for Nigerian naira.</span></div><div class="form-field"><label for="date-format">Date display</label><select id="date-format" name="dateFormat"><option value="DD/MM/YYYY" ${db.settings.dateFormat==="DD/MM/YYYY"?"selected":""}>DD/MM/YYYY</option><option value="MMM DD, YYYY" ${db.settings.dateFormat==="MMM DD, YYYY"?"selected":""}>MMM DD, YYYY</option></select></div></div><div class="settings-actions"><button class="btn btn-primary" type="submit">Save preferences</button><button class="btn btn-secondary" type="button" data-action="backup">${U.icon("download")} Download JSON backup</button><label class="btn btn-secondary" for="restore-file">Restore backup<input id="restore-file" type="file" accept="application/json,.json" hidden></label></div></form><div class="notice warning" style="margin-top:22px"><strong>Demo data and privacy</strong><br>This version stores information in this browser only. It has no login, cloud sync, encryption, or server database. Use fictional data for testing; do not rely on it for sensitive tenant records.</div><div class="settings-actions"><button class="btn btn-danger" data-action="reset-demo">Reset all demo data</button></div></section></div>`;
  }
  function openModal({title,subtitle="",body="",submit="Save",onSubmit=null,wide=false}){
    modalRoot.innerHTML=`<div class="modal-backdrop" role="presentation"><section class="modal ${wide?"wide":""}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></header><form id="modal-form"><div class="modal-body">${body}</div><footer class="modal-footer"><button type="button" class="btn btn-secondary" data-action="close-modal">Cancel</button><button type="submit" class="btn btn-primary">${submit}</button></footer></form></section></div>`;
    const form=modalRoot.querySelector("#modal-form");form.addEventListener("submit",e=>{e.preventDefault();try{if(onSubmit)onSubmit(new FormData(form));}catch(err){U.toast(err.message||"Please check the form.","error");}});
    modalRoot.querySelector(".modal-backdrop").addEventListener("click",e=>{if(e.target.classList.contains("modal-backdrop"))closeModal();});
    const first=modalRoot.querySelector("input:not([type=hidden]),select,textarea");if(first)first.focus();
  }
  function closeModal(){modalRoot.innerHTML="";}
  const field=(label,name,value="",type="text",required=true,extra="")=>`<div class="form-field"><label for="f-${name}">${label}${required?" *":""}</label><input id="f-${name}" name="${name}" type="${type}" value="${U.esc(value)}" ${required?"required":""} ${extra}></div>`;
  const selectField=(label,name,options,value="",required=true)=>`<div class="form-field"><label for="f-${name}">${label}${required?" *":""}</label><select id="f-${name}" name="${name}" ${required?"required":""}>${options.map(o=>`<option value="${U.esc(o.value)}" ${o.value===value?"selected":""}>${U.esc(o.label)}</option>`).join("")}</select></div>`;
  function propertyForm(id=""){
    const p=id?P.getById(db,id):null;
    openModal({title:p?"Edit property":"Add a property",subtitle:"Property details help keep your portfolio organized.",body:`<div class="form-grid">${field("Property name","name",p?.name||"")}${selectField("Property type","type",["Apartment block","Residential","Duplex","Terrace","Commercial"].map(x=>({value:x,label:x})),p?.type||"Apartment block")}${field("Address","address",p?.address||"","text",true,'class="full"')}${`<div class="form-field full"><label for="f-description">Description</label><textarea id="f-description" name="description" placeholder="Optional notes about the property">${U.esc(p?.description||"")}</textarea></div>`}</div>`,onSubmit:fd=>{const name=String(fd.get("name")).trim(),address=String(fd.get("address")).trim();if(!name||!address)throw new Error("Property name and address are required.");if(p){Object.assign(p,{name,address,type:fd.get("type"),description:fd.get("description")});}else P.addProperty(db,{id:U.id("p"),name,address,type:fd.get("type"),description:fd.get("description"),createdAt:U.today(),archived:false});save();closeModal();render();U.toast(p?"Property updated.":"Property added.");}});
  }
  function tenantForm(id=""){
    const t=id?T.getById(db,id):null;
    openModal({title:t?"Edit tenant":"Add a tenant",subtitle:"Keep contact details accurate for day-to-day management.",body:`<div class="form-grid">${field("Full name","fullName",t?.fullName||"")}${field("Phone number","phone",t?.phone||"","tel")}${field("Email address","email",t?.email||"","email",false)}${field("Emergency contact","emergencyContact",t?.emergencyContact||"","text",false)}<div class="form-field full"><label for="f-notes">Notes</label><textarea id="f-notes" name="notes">${U.esc(t?.notes||"")}</textarea></div></div>`,onSubmit:fd=>{const fullName=String(fd.get("fullName")).trim(),phone=String(fd.get("phone")).trim();if(!fullName||!phone)throw new Error("Name and phone number are required.");const data={fullName,phone,email:String(fd.get("email")).trim(),emergencyContact:String(fd.get("emergencyContact")).trim(),notes:fd.get("notes")};if(t)Object.assign(t,data);else db.tenants.push({id:U.id("t"),...data,createdAt:U.today(),archived:false});save();closeModal();render();U.toast(t?"Tenant updated.":"Tenant added.");}});
  }
  function unitForm(propertyId="",unitId=""){
    const unit=unitId?unitById(unitId):null;const props=db.properties.filter(p=>!p.archived);
    openModal({title:unit?"Edit unit":"Add a unit",subtitle:"Units belong to a property and may have one active lease at a time.",body:`<div class="form-grid">${selectField("Property","propertyId",props.map(p=>({value:p.id,label:p.name})),unit?.propertyId||propertyId||props[0]?.id||"")}${field("Unit number","unitNumber",unit?.unitNumber||"")}${selectField("Unit type","unitType",["Studio","1 Bedroom","2 Bedroom","3 Bedroom","4 Bedroom","Commercial","Other"].map(x=>({value:x,label:x})),unit?.unitType||"2 Bedroom")}${field("Monthly rent (₦)","monthlyRent",unit?.monthlyRent||"","number",true,'min="1" step="1"')}${`<div class="form-field full"><label for="f-notes">Notes</label><textarea id="f-notes" name="notes">${U.esc(unit?.notes||"")}</textarea></div>`}</div>`,onSubmit:fd=>{const unitNumber=String(fd.get("unitNumber")).trim(),propId=fd.get("propertyId"),rent=Number(fd.get("monthlyRent"));if(!unitNumber||!rent||rent<1)throw new Error("Enter a unit number and positive monthly rent.");if(db.units.some(u=>u.propertyId===propId&&u.unitNumber.toLowerCase()===unitNumber.toLowerCase()&&u.id!==unitId&&!u.archived))throw new Error("That unit number already exists for this property.");if(unit)Object.assign(unit,{propertyId:propId,unitNumber,unitType:fd.get("unitType"),monthlyRent:rent,notes:fd.get("notes")});else P.addUnit(db,{id:U.id("u"),propertyId:propId,unitNumber,unitType:fd.get("unitType"),monthlyRent:rent,notes:fd.get("notes"),archived:false});save();closeModal();render();U.toast(unit?"Unit updated.":"Unit added.");}});
  }
  function leaseForm(){
    const tenants=db.tenants.filter(t=>!t.archived),units=db.units.filter(u=>!u.archived);
    openModal({title:"Create a lease",subtitle:"Leases preserve tenancy history and prevent overlapping unit assignments.",body:`<div class="form-grid">${selectField("Tenant","tenantId",tenants.map(t=>({value:t.id,label:t.fullName})),tenants[0]?.id||"")}${selectField("Unit","unitId",units.map(u=>({value:u.id,label:`${propertyName(u.propertyId)} · ${u.unitNumber}`})),units[0]?.id||"")}${field("Lease start","startDate",U.today(),"date")}${field("Lease end","endDate",new Date(Date.now()+365*86400000).toISOString().slice(0,10),"date")}${field("Monthly rent (₦)","rentAmount",units[0]?.monthlyRent||"","number",true,'min="1" step="1"')}${field("Rent due day","dueDay","1","number",true,'min="1" max="31"') }<div class="form-field full"><div class="notice">This creates a lease record only. Use “Create rent due” to create rent obligations for the periods you want to track.</div></div></div>`,onSubmit:fd=>{const startDate=fd.get("startDate"),endDate=fd.get("endDate"),unitId=fd.get("unitId"),rentAmount=Number(fd.get("rentAmount")),dueDay=Number(fd.get("dueDay"));if(endDate<startDate)throw new Error("Lease end date must be on or after the start date.");if(L.overlaps(db,unitId,startDate,endDate))throw new Error("This unit already has a lease overlapping those dates.");if(rentAmount<=0||dueDay<1||dueDay>31)throw new Error("Enter a valid rent amount and due day.");db.leases.push({id:U.id("l"),tenantId:fd.get("tenantId"),unitId,startDate,endDate,rentAmount,dueDay,status:"active"});save();closeModal();render();U.toast("Lease created.");}});
  }
  function obligationForm(){
    const leases=db.leases.filter(l=>l.status==="active");
    openModal({title:"Create rent obligation",subtitle:"Add a rent amount due for a specific period. Duplicate periods are blocked.",body:`<div class="form-grid">${selectField("Lease / tenant","leaseId",leases.map(l=>({value:l.id,label:`${tenantName(l.tenantId)} · ${unitById(l.unitId)?.unitNumber||""}`})),leases[0]?.id||"")}${field("Period start","periodStart",new Date().toISOString().slice(0,7)+"-01","date")}${field("Period end","periodEnd",new Date(new Date().getFullYear(),new Date().getMonth()+1,0).toISOString().slice(0,10),"date")}${field("Due date","dueDate",new Date().toISOString().slice(0,7)+"-01","date")}${field("Amount due (₦)","amountDue",leases[0]?.rentAmount||"","number",true,'min="1" step="1"')}</div>`,onSubmit:fd=>{const lease=leaseById(fd.get("leaseId")),periodStart=fd.get("periodStart"),periodEnd=fd.get("periodEnd"),dueDate=fd.get("dueDate"),amountDue=Number(fd.get("amountDue"));if(!lease)throw new Error("Select a valid lease.");if(periodEnd<periodStart||dueDate<periodStart)throw new Error("Check the rent period and due date.");if(amountDue<=0)throw new Error("Amount due must be positive.");if(db.obligations.some(o=>o.leaseId===lease.id&&o.periodStart===periodStart))throw new Error("An obligation already exists for this lease and period.");db.obligations.push({id:U.id("o"),leaseId:lease.id,periodStart,periodEnd,dueDate,amountDue});save();closeModal();render();U.toast("Rent obligation created.");}});
  }
  function paymentForm(obligationId=""){
    const obligations=db.obligations.filter(o=>Pay.balance(db,o)>0),selected=obligations.find(o=>o.id===obligationId)||obligations[0];
    if(!selected){U.toast("There are no outstanding balances to pay.","error");return;}
    openModal({title:"Record a payment",subtitle:"Partial payments are supported. Voided payments are excluded from totals.",body:`<div class="form-grid">${selectField("Rent obligation","obligationId",obligations.map(o=>({value:o.id,label:`${obligationTenant(o)} · ${U.date(o.periodStart)} · balance ${U.money(Pay.balance(db,o))}`})),selected.id)}${field("Amount received (₦)","amount",Pay.balance(db,selected),"number",true,'min="1" step="1"')}${field("Payment date","paymentDate",U.today(),"date")}${selectField("Payment method","method",["Bank transfer","Cash","POS","Cheque","Other"].map(x=>({value:x,label:x})),"Bank transfer")}${field("Reference / receipt no.","reference",`RF-${String(db.payments.length+1001)}`,"text",false)}<div class="form-field full"><div class="notice" id="payment-balance-note">Remaining balance: ${U.money(Pay.balance(db,selected))}</div></div></div>`,onSubmit:fd=>{const obligation=db.obligations.find(o=>o.id===fd.get("obligationId")),amount=Number(fd.get("amount"));if(!obligation)throw new Error("Select an obligation.");if(amount<=0)throw new Error("Payment must be greater than zero.");if(amount>Pay.balance(db,obligation))throw new Error("Payment exceeds the outstanding balance. Advance credits are not supported in V1.");const paymentDate=fd.get("paymentDate");if(!paymentDate)throw new Error("Enter a payment date.");db.payments.push({id:U.id("pay"),obligationId:obligation.id,amount,paymentDate,method:fd.get("method"),reference:String(fd.get("reference")).trim(),status:"valid"});save();closeModal();render();U.toast("Payment recorded.");}});
  }
  function maintenanceForm(id=""){
    const item=id?db.maintenance.find(m=>m.id===id):null,props=db.properties.filter(p=>!p.archived),units=db.units.filter(u=>!u.archived),tenants=db.tenants.filter(t=>!t.archived);
    openModal({title:item?"Update maintenance request":"New maintenance request",subtitle:"Record the issue, priority, status, and costs.",body:`<div class="form-grid">${field("Request title","title",item?.title||"")}${selectField("Property","propertyId",props.map(p=>({value:p.id,label:p.name})),item?.propertyId||props[0]?.id||"")}${selectField("Unit (optional)","unitId",[{value:"",label:"Property-wide / not assigned"},...units.map(u=>({value:u.id,label:`${propertyName(u.propertyId)} · ${u.unitNumber}`}))],item?.unitId||"",false)}${selectField("Tenant (optional)","tenantId",[{value:"",label:"No tenant linked"},...tenants.map(t=>({value:t.id,label:t.fullName}))],item?.tenantId||"",false)}${selectField("Priority","priority",["low","medium","high","urgent"].map(x=>({value:x,label:x[0].toUpperCase()+x.slice(1)})),item?.priority||"medium")}${selectField("Status","status",["open","in-progress","completed","cancelled"].map(x=>({value:x,label:x==="in-progress"?"In progress":x[0].toUpperCase()+x.slice(1)})),item?.status||"open")}${field("Reported date","reportedAt",item?.reportedAt||U.today(),"date")}${field("Cost (₦)","cost",item?.cost||0,"number",true,'min="0" step="1"')}${`<div class="form-field full"><label for="f-description">Description</label><textarea id="f-description" name="description">${U.esc(item?.description||"")}</textarea></div>`}</div>`,onSubmit:fd=>{const propertyId=fd.get("propertyId"),unitId=fd.get("unitId")||"",cost=Number(fd.get("cost"));if(unitId&&unitById(unitId)?.propertyId!==propertyId)throw new Error("The selected unit does not belong to this property.");if(cost<0)throw new Error("Cost cannot be negative.");const status=fd.get("status"),data={title:String(fd.get("title")).trim(),propertyId,unitId,tenantId:fd.get("tenantId")||"",priority:fd.get("priority"),status,reportedAt:fd.get("reportedAt"),cost,description:fd.get("description"),completedAt:status==="completed"?(item?.completedAt||U.today()):""};if(!data.title)throw new Error("Enter a request title.");if(item)Object.assign(item,data);else db.maintenance.push({id:U.id("m"),...data});save();closeModal();render();U.toast(item?"Maintenance request updated.":"Maintenance request created.");}});
  }
  function viewProperty(id){
    const p=P.getById(db,id);if(!p)return;const units=P.units(db,id),occupied=P.occupiedUnitIds(db);
    openModal({title:U.esc(p.name),subtitle:U.esc(p.address),wide:true,submit:"Add unit",body:`<p class="muted" style="margin-top:0">${U.esc(p.description||"No description added.")}</p><div class="detail-grid"><div class="detail-item"><small>Property type</small><strong>${U.esc(p.type)}</strong></div><div class="detail-item"><small>Total units</small><strong>${units.length}</strong></div></div><div style="display:flex;align-items:center;justify-content:space-between;margin:22px 0 8px"><h3 style="font-size:13px;margin:0">Units</h3><span class="muted">${units.filter(u=>occupied.has(u.id)).length} occupied</span></div><div class="table-wrap"><table class="responsive-table"><thead><tr><th>Unit</th><th>Type</th><th>Monthly rent</th><th>Status</th><th>Actions</th></tr></thead><tbody>${units.map(u=>`<tr><td data-label="Unit">${U.esc(u.unitNumber)}</td><td data-label="Type">${U.esc(u.unitType)}</td><td data-label="Monthly rent">${U.money(u.monthlyRent)}</td><td data-label="Status">${U.badge(occupied.has(u.id)?"active":"available",occupied.has(u.id)?"Occupied":"Available")}</td><td data-label="Actions"><button class="btn btn-secondary btn-sm" type="button" data-action="edit-unit" data-id="${u.id}">Edit</button></td></tr>`).join("")||`<tr><td colspan="5">No units yet.</td></tr>`}</tbody></table></div>`,onSubmit:()=>{closeModal();unitForm(id);}});
  }
  function viewTenant(id){
    const t=T.getById(db,id);if(!t)return;const leases=T.history(db,id);
    openModal({title:U.esc(t.fullName),subtitle:"Tenant profile and lease history",body:`<div class="detail-grid"><div class="detail-item"><small>Phone</small><strong>${U.esc(t.phone)}</strong></div><div class="detail-item"><small>Email</small><strong>${U.esc(t.email||"Not provided")}</strong></div><div class="detail-item"><small>Emergency contact</small><strong>${U.esc(t.emergencyContact||"Not provided")}</strong></div><div class="detail-item"><small>Profile created</small><strong>${U.date(t.createdAt)}</strong></div></div><div style="margin-top:18px"><h3 style="font-size:13px">Lease history</h3>${leases.length?leases.map(l=>`<div class="mini-row"><span class="mini-avatar">${U.icon("building")}</span><div class="mini-main"><strong>${U.esc(unitLabel(l.unitId))}</strong><small>${U.date(l.startDate)} – ${U.date(l.endDate)}</small></div><div class="mini-amount">${U.money(l.rentAmount)}<small>${U.badge(l.status)}</small></div></div>`).join(""):`<p class="muted">No lease history.</p>`}</div>${t.notes?`<div class="notice" style="margin-top:14px">${U.esc(t.notes)}</div>`:""}`,submit:"Edit tenant",onSubmit:()=>{closeModal();tenantForm(id);}});
  }
  function viewMaintenance(id){
    const m=db.maintenance.find(x=>x.id===id);if(!m)return;
    openModal({title:U.esc(m.title),subtitle:`${U.esc(propertyName(m.propertyId))} · ${U.esc(unitById(m.unitId)?.unitNumber||"Property-wide")}`,body:`<div class="detail-grid"><div class="detail-item"><small>Priority</small><strong>${U.badge(m.priority)}</strong></div><div class="detail-item"><small>Status</small><strong>${U.badge(m.status)}</strong></div><div class="detail-item"><small>Reported</small><strong>${U.date(m.reportedAt)}</strong></div><div class="detail-item"><small>Recorded cost</small><strong>${U.money(m.cost)}</strong></div><div class="detail-item"><small>Tenant</small><strong>${U.esc(tenantName(m.tenantId))}</strong></div><div class="detail-item"><small>Completed</small><strong>${U.date(m.completedAt)}</strong></div></div><p style="margin-bottom:0;color:#69748a;font-size:12px">${U.esc(m.description||"No additional description.")}</p>`,submit:"Edit request",onSubmit:()=>{closeModal();maintenanceForm(id);}});
  }
  function viewObligation(id){
    const o=db.obligations.find(x=>x.id===id);if(!o)return;const payments=db.payments.filter(p=>p.obligationId===id).sort((a,b)=>b.paymentDate.localeCompare(a.paymentDate));
    openModal({title:"Rent payment history",subtitle:`${U.esc(obligationTenant(o))} · ${U.date(o.periodStart)} – ${U.date(o.periodEnd)}`,body:`<div class="detail-grid"><div class="detail-item"><small>Amount due</small><strong>${U.money(o.amountDue)}</strong></div><div class="detail-item"><small>Paid so far</small><strong>${U.money(Pay.paid(db,o.id))}</strong></div><div class="detail-item"><small>Outstanding</small><strong>${U.money(Pay.balance(db,o))}</strong></div><div class="detail-item"><small>Status</small><strong>${U.badge(Pay.status(db,o))}</strong></div></div><h3 style="font-size:13px;margin-top:20px">Transactions</h3>${payments.length?payments.map(p=>`<div class="mini-row"><span class="mini-avatar">${U.icon("wallet")}</span><div class="mini-main"><strong>${U.money(p.amount)}</strong><small>${U.date(p.paymentDate)} · ${U.esc(p.method)} · ${U.esc(p.reference||"No reference")}</small></div><div class="mini-amount">${p.status==="valid"?U.badge("paid","Valid"):U.badge("cancelled","Voided")}<small>${p.status==="valid"?`<button class="text-link" data-action="void-payment" data-id="${p.id}">Void</button>`:""}</small></div></div>`).join(""):`<p class="muted">No payments recorded.</p>`}`,submit:Pay.balance(db,o)>0?"Record payment":"Close",onSubmit:()=>{closeModal();if(Pay.balance(db,o)>0)paymentForm(id);else closeModal();}});
  }
  function confirmReset(){
    openModal({title:"Reset demo data?",subtitle:"This replaces all current browser data with the original fictional sample records.",body:`<div class="notice warning">This action cannot be undone. Download a JSON backup first if you want to keep your current demo changes.</div>`,submit:"Reset demo",onSubmit:()=>{db=window.RentFlowStorage.reset();currentPage="dashboard";propertySearch="";tenantSearch="";closeModal();render();U.toast("Demo data restored.");}});
  }
  function showAlerts(){
    const expiring=db.leases.filter(l=>l.status==="active"&&l.endDate>=U.today()&&l.endDate<=new Date(Date.now()+30*86400000).toISOString().slice(0,10));
    const overdue=db.obligations.filter(o=>Pay.status(db,o)==="overdue");
    openModal({title:"Your alerts",subtitle:"Items to review in your rental portfolio.",body:`${overdue.length?`<div class="notice-card" style="margin-bottom:10px"><span>!</span><div><strong>${overdue.length} overdue rent obligation${overdue.length===1?"":"s"}</strong><p>${U.money(overdue.reduce((s,o)=>s+Pay.balance(db,o),0))} outstanding in overdue rent.</p></div></div>`:`<div class="notice" style="margin-bottom:10px">No overdue rent obligations right now.</div>`}${expiring.length?`<div class="notice-card"><span>◷</span><div><strong>${expiring.length} lease${expiring.length===1?"":"s"} expiring within 30 days</strong><p>${expiring.map(l=>`${U.esc(tenantName(l.tenantId))} · ${U.date(l.endDate)}`).join("<br>")}</p></div></div>`:`<div class="notice">No lease expirations in the next 30 days.</div>`}`,submit:"View rent",onSubmit:()=>{closeModal();currentPage="payments";render();}});
  }
  function exportTenants(){U.csv("rentflow-tenants.csv",[["Name","Phone","Email","Current unit","Lease end"],...db.tenants.filter(t=>!t.archived).map(t=>{const l=T.currentLease(db,t.id);return[t.fullName,t.phone,t.email, l?unitLabel(l.unitId):"",l?.endDate||""]})]);}
  function exportPayments(){U.csv("rentflow-rent-obligations.csv",[["Tenant","Unit","Period start","Period end","Due date","Amount due","Paid","Balance","Status"],...db.obligations.map(o=>{const l=obligationLease(o);return[obligationTenant(o),unitLabel(l?.unitId),o.periodStart,o.periodEnd,o.dueDate,o.amountDue,Pay.paid(db,o.id),Pay.balance(db,o),Pay.status(db,o)]})]);}
  function exportMaintenance(){U.csv("rentflow-maintenance.csv",[["Title","Property","Unit","Tenant","Priority","Status","Reported","Completed","Cost"],...db.maintenance.map(m=>[m.title,propertyName(m.propertyId),unitById(m.unitId)?.unitNumber||"",tenantName(m.tenantId),m.priority,m.status,m.reportedAt,m.completedAt,m.cost])]);}
  function exportReport(){U.csv("rentflow-report.csv",[["Metric","Value"],["Report start",reportStart],["Report end",reportEnd],["Rent collected",Pay.collected(db,reportStart,reportEnd)],["Rent due",R.rentDue(db,reportStart,reportEnd)],["Maintenance costs",M.expenses(db,reportStart,reportEnd)],["Outstanding as of today",R.outstanding(db)]]);}
  function handleAction(action,id){
    switch(action){
      case "close-modal":closeModal();break;
      case "add-property":propertyForm();break;
      case "edit-property":propertyForm(id);break;
      case "view-property":viewProperty(id);break;
      case "add-unit":unitForm();break;
      case "edit-unit":closeModal();unitForm("",id);break;
      case "add-tenant":tenantForm();break;
      case "edit-tenant":tenantForm(id);break;
      case "view-tenant":viewTenant(id);break;
      case "add-lease":leaseForm();break;
      case "add-obligation":obligationForm();break;
      case "add-payment":paymentForm();break;
      case "pay-obligation":paymentForm(id);break;
      case "view-obligation":viewObligation(id);break;
      case "add-maintenance":maintenanceForm();break;
      case "edit-maintenance":maintenanceForm(id);break;
      case "view-maintenance":viewMaintenance(id);break;
      case "export-tenants":exportTenants();break;
      case "export-payments":exportPayments();break;
      case "export-maintenance":exportMaintenance();break;
      case "export-report":exportReport();break;
      case "apply-report":{const start=document.getElementById("report-start").value,end=document.getElementById("report-end").value;if(!start||!end||end<start){U.toast("Choose a valid reporting date range.","error");break;}reportStart=start;reportEnd=end;render();break;}
      case "backup":U.downloadJSON("rentflow-backup.json",db);break;
      case "reset-demo":confirmReset();break;
      case "notifications":showAlerts();break;
      case "void-payment":{const p=db.payments.find(x=>x.id===id);if(!p||p.status!=="valid")break;if(confirm("Void this payment? It will remain in the history but will no longer count toward rent collected.")){p.status="void";save();closeModal();render();U.toast("Payment voided.");}break;}
      case "export-report":exportReport();break;
    }
  }
  document.addEventListener("click",e=>{
    const pageBtn=e.target.closest("[data-page]");if(pageBtn){e.preventDefault();currentPage=pageBtn.dataset.page;closeModal();closeSidebar();render();return;}
    const btn=e.target.closest("[data-action]");if(btn){e.preventDefault();handleAction(btn.dataset.action,btn.dataset.id||"");}
  });
  content.addEventListener("input",e=>{
    if(e.target.id==="property-search"){propertySearch=e.target.value;const pos=e.target.selectionStart;render();const n=document.getElementById("property-search");n?.focus();n?.setSelectionRange(pos,pos);}
    if(e.target.id==="tenant-search"){tenantSearch=e.target.value;const pos=e.target.selectionStart;render();const n=document.getElementById("tenant-search");n?.focus();n?.setSelectionRange(pos,pos);}
  });
  content.addEventListener("change",e=>{
    if(e.target.id==="payment-filter"){paymentFilter=e.target.value;render();}
    if(e.target.id==="maintenance-filter"){maintenanceFilter=e.target.value;render();}
  });
  document.getElementById("global-search").addEventListener("input",e=>globalSearch(e.target.value));
  document.getElementById("mobile-search").addEventListener("input",e=>globalSearch(e.target.value));
  function globalSearch(query){const q=query.trim().toLowerCase();if(!q)return;const tenant=db.tenants.find(t=>t.fullName.toLowerCase().includes(q));const prop=db.properties.find(p=>p.name.toLowerCase().includes(q)||p.address.toLowerCase().includes(q));if(tenant){currentPage="tenants";tenantSearch=query;render();}else if(prop){currentPage="properties";propertySearch=query;render();}}
  document.getElementById("notifications-button").addEventListener("click",()=>showAlerts());
  const sidebar=document.getElementById("sidebar"),scrim=document.getElementById("sidebar-scrim"),menu=document.getElementById("menu-toggle");
  function closeSidebar(){sidebar.classList.remove("open");scrim.classList.remove("visible");menu.setAttribute("aria-expanded","false");}
  menu.addEventListener("click",()=>{const open=!sidebar.classList.contains("open");sidebar.classList.toggle("open",open);scrim.classList.toggle("visible",open);menu.setAttribute("aria-expanded",String(open));});
  scrim.addEventListener("click",closeSidebar);
  document.addEventListener("keydown",e=>{if(e.key==="Escape")closeModal();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==="k"){e.preventDefault();const input=window.matchMedia("(max-width: 760px)").matches?document.getElementById("mobile-search"):document.getElementById("global-search");input.focus();}});
  document.addEventListener("submit",e=>{
    if(e.target.id==="settings-form"){e.preventDefault();const fd=new FormData(e.target);db.settings.ownerName=String(fd.get("ownerName")).trim();db.settings.businessName=String(fd.get("businessName")).trim();db.settings.dateFormat=fd.get("dateFormat");save();U.toast("Preferences saved.");render();}
  });
  content.addEventListener("change",e=>{
    if(e.target.id==="restore-file"){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result);const keys=["properties","units","tenants","leases","obligations","payments","maintenance","settings"];if(parsed.schemaVersion!==1||!keys.every(k=>Array.isArray(parsed[k])||k==="settings"&&parsed[k]&&typeof parsed[k]==="object"))throw new Error("This does not look like a valid RentFlow backup.");if(!confirm("Restore this backup? Current data will be replaced."))return;db=parsed;save();render();U.toast("Backup restored.");}catch(err){U.toast(err.message||"Could not restore this file.","error");}};reader.readAsText(file);}
  });
  render();
})();
